  ["8732e2a91a4fe3c6"] = { "Bloodhoof Villageの東側に大きなテントがあります。そこでNarm Skychaserがあなたを待っています。", "." },
  ["873bbd121f923a1f"] = { "不快な場所だな、この「Undercity」というのは。昔のLordaeronとは似ても似つかぬ。あの頃が懐かしい……\n\nStratholmeへ行きたいのなら、あいにく今はお力になれない。燃える街の近くの塔はまだ争奪戦の最中で、そのため私の力はあまりに弱く、あなたを助けられないのだ。あちらで勝利したら、また私のところへ来てくれ。", "." },
  ["873d42d17f1de9dc"] = { "Frostwolf Relief Hutが攻撃を受けている！放っておけば、Hordeに占領されるぞ！", "." },
  ["873e53ad9401fbd7"] = { "<Ayessa Dawnsingerは、かろうじて抑えた怒りを込めてあなたを睨んでいる。>\n\nWindshaperの血を流しておきながら、これほど厚かましく我らの領域に足を踏み入れるとは、よほど大胆か、よほど愚かかのどちらかだな。我らは許すのに時間がかかり、そして決して忘れない。\n\n今すぐここから立ち去るがいい。ここがZephrasの中心でなければ、お前はとうに死んでいるところだ。", "." },
  ["8743c613911c68c0"] = { "うん、問題ないよ、{name}! ごめん……もう使い終わったのかと思ってた。", "." },
