  ["876a22d5942b22ac"] = { "Razor Hillにある大きな建物で、兵舎じゃないほうだ。中にいるInnkeeper Groskに話しかけるだけでいい。わかったか?", "." },
  ["877dfc5fba9e3824"] = { "気を抜くな、この怠け者のラバどもめ！", "." },
