  ["87829f10ac48ecfa"] = { "お前さんは鍛冶屋の顔をしているな。爪の間には煤、骨には鋼。ああ、間違いなく鍛冶屋の血が流れている。つまり、何か学びたくて俺のところへ来たということだ。よし若いの、ハンマーを取れ。何を教えてやれるか見てみようじゃないか。", "." },
  ["87859dc7ab542729"] = { "確かに、ふさわしい者に教える技を私は持っている。それはあなただろうか?", "." },
  ["8788490a4d2d5c8e"] = { "Greatfather Winterからのよろしくを伝えてやろう、クズめ……", "." },
  ["878be02303428baf"] = { "私がすごいと思うなら、夫の戦いぶりを見てみなさい。", "." },
  ["878f2a70d4117deb"] = { "Evershineをタンクに入れて、あいつらが気づく前に家へ帰ってたのに！", "." },
  ["878fb61f93b25193"] = { "Radnaalなら、Darnassusへ続く道沿いにある自宅の外で技を磨いています。立ち寄って、何を教えてもらえるか確かめるとよいでしょう。", "." },
  ["879982941286b0cc"] = { "それはひどい。", "." },
