  ["87a36aabe529dcf1"] = { "遊びに来たのか？ならば遊ぼうではないか！", "." },
  ["87a4a4575ed0e07d"] = { "そうだ、ええと、若いの、軍需物資はすべてSilithusへ運ばれているところで、最後の分も$2113w日以内に届くはずだ。その後は、誰が英雄を送り出してScepter of the Shifting Sandsを再生させ、Scarab Daisの銅鑼を鳴らすのか、皆で待つしかない。それが起きて初めて、戦争が始まりAhn'Qirajの門が開かれるのだ。", "." },
  ["87a73864de8a56fd"] = { "Mudskunksは熱帯の海を好む、特に臭い種類の魚だ。Zulian Mudskunkは中でも一番臭くて、Zul'Gurubの蒸し暑い水域でしか見つからない。\n\nGahz'rankaをあの場所に引き寄せたのはZulian Mudskunksだと私は思っている。もっとも、トロールどもは奴が自分たちの神の一柱だと言うだろうがね……\n\n好きに信じればいい。だが覚えておけ。私のルアーの一つにZulian Mudskunksを詰めれば、あの老いぼれは必ずやって来るとも!", "." },
  ["87aad64f9aadfc7e"] = { "侵入者だ！殺せ！部屋に入れるな！", "." },
