  ["87baf82cc0ae7514"] = { "ここの復興を手伝いにIronforgeから来たんだ。十分な数のお前さんたちに技を教えられたら、後はお前さんたちに任せて故郷へ帰れるかもしれんな。", "." },
  ["87bbc0c2d6576088"] = { "自分が十分賢いと思うか? 必要なものを持っていると思うか? 確かめてみようじゃないか!", "." },
  ["87bfee5c3f6f80db"] = { "このサンプルを見てくれ! これはどういう意味だ? どういう意味なんだ? 時間が必要だ、この情報を全部調べる時間が。それにもっと情報が要る。手に入らない情報が……くそっ! 考えろ、Laris、考えるんだ!\n\nどうするつもりだ? どうする?!\n\n解決策があるはずだ!", "." },
  ["87c249787898ccff"] = { "助けて！身を守るのに片手しかないんだ。", "." },
